-- 452: PAYMENTS MADE CLEARER IN THE COMMUNITY TERMS AND THE VIP AGREEMENT (21 Oct 2026, Ethan's request).
-- A Chilean creator wanted to be paid in pesos into a Chilean account; we cannot. The two published documents now say
-- exactly what we pay into (SEPA area accounts in euro or their local currency, UK accounts in pounds) and that any cash
-- prize / VIP balance can always be taken as a Tryp.com voucher of the same value, so everyone can always be paid.
--
-- NO RE-ACCEPTANCE: this is a clarification of how payment already works, not a new obligation, so the published rows are
-- amended IN PLACE (no new version, so my_pending_agreements stays empty for everyone who has already accepted). Every
-- acceptance keeps its own exact rendered_body + sha256, so what each person actually accepted is untouched.
-- The translation lock trigger is off only for this block and straight back on. Each edit is an asserted string
-- replacement: if the live text has drifted, the whole migration fails instead of shipping half-patched.
create or replace function pg_temp.patch(p_in text, p_anchor text, p_add text) returns text
language plpgsql as $f$
declare v text;
begin
  if position(p_anchor in p_in) = 0 then raise exception 'ANCHOR NOT FOUND: %', left(p_anchor, 60); end if;
  v := replace(p_in, p_anchor, p_anchor || p_add);
  if v = p_in then raise exception 'NO CHANGE: %', left(p_anchor, 60); end if;
  return v;
end $f$;

alter table public.agreement_translations disable trigger trg_agreement_translation_locked;

do $m$
declare c uuid := 'ba59ca85-d630-4fd0-bea9-c58c243d5132'; v uuid := 'c9705ec2-c818-4d59-9f87-1635505bab65';
begin
  update public.agreements set
    body = pg_temp.patch(pg_temp.patch(body, $q$- **Cash prizes** are paid by bank transfer against an invoice we prepare for you from the payment details you save (self-billing), normally within 30 days of results being published. You must keep those details correct; we cannot recover money sent to an account you gave us.$q$, E'\n' || $q$- **Where and in what currency we pay.** We pay by bank transfer into bank accounts in the **SEPA area** (in euro, or in the local currency of a SEPA country, for example Czech koruna, Norwegian krone, Swedish krona, Danish krone, Polish zloty or Romanian leu) and into **UK bank accounts in pounds sterling**. We cannot pay into accounts outside the SEPA area and the UK, or in other currencies (for example a Chilean peso account).$q$ || E'\n' || $q$- **Everyone can always be rewarded.** If you cannot receive a transfer to an account we support, or would simply prefer not to, you can take any cash prize as a **Tryp.com voucher of the same value** instead. Just ask the team (ethan@tryp.com, or a message in the app) and we will issue it.$q$), $q$Every version you accepted stays available in **Settings > Agreements**.$q$, $q$ Small clarifications that only explain how something already works, such as which bank accounts and currencies we pay, are shown in the app and apply straight away, without you needing to accept again.$q$),
    change_note = 'Payments clarified 21 Oct 2026: which accounts and currencies we pay, and that a cash prize can always be taken as a voucher of the same value. A clarification, no new acceptance needed.',
    updated_at = now()
   where id = c and published_at is not null;
  update public.agreements set
    body = pg_temp.patch(body, $q$- **7.7 Tax.** The Creator is an independent contractor and is responsible for declaring and paying all taxes and social contributions on what they earn, in their own country.$q$, E'\n' || $q$- **7.8 Accounts, currencies and vouchers.** Tryp.com pays by bank transfer into bank accounts in the **SEPA area** (in euro, or in the local currency of a SEPA country, for example Czech koruna, Norwegian krone, Swedish krona, Danish krone, Polish zloty or Romanian leu) and into **UK bank accounts in pounds sterling**. Tryp.com cannot pay into accounts outside the SEPA area and the UK, or in other currencies (for example a Chilean peso account). A Creator who cannot or would rather not receive a transfer can always take the amount as a **Tryp.com travel voucher of the same value** instead (on the terms of clause 7.4), so every Creator can always be paid.$q$),
    change_note = 'Payments clarified 21 Oct 2026: new clause 7.8 on accounts, currencies and the voucher option. A clarification, no new signature needed.',
    updated_at = now()
   where id = v and published_at is not null;
  update public.agreement_translations set body = pg_temp.patch(pg_temp.patch(body, $q$- **Los premios en efectivo** se pagan por transferencia bancaria contra una factura que preparamos por ti con los datos de pago que guardes (autofacturación), normalmente en los 30 días siguientes a la publicación de los resultados. Debes mantener esos datos correctos; no podemos recuperar dinero enviado a una cuenta que nos diste.$q$, E'\n' || $q$- **Dónde y en qué moneda pagamos.** Pagamos por transferencia bancaria a cuentas de la **zona SEPA** (en euros, o en la moneda local de un país SEPA, por ejemplo corona checa, corona noruega, corona sueca, corona danesa, esloti polaco o leu rumano) y a **cuentas bancarias del Reino Unido en libras esterlinas**. No podemos pagar en cuentas fuera de la zona SEPA y del Reino Unido, ni en otras monedas (por ejemplo, una cuenta en pesos chilenos).$q$ || E'\n' || $q$- **Todo el mundo puede recibir siempre su recompensa.** Si no puedes recibir una transferencia en una cuenta que admitimos, o simplemente prefieres no hacerlo, puedes recibir cualquier premio en efectivo como un **vale de Tryp.com por el mismo valor**. Solo tienes que pedírselo al equipo (ethan@tryp.com o un mensaje en la app) y te lo emitimos.$q$), $q$siguen disponibles en **Ajustes > Acuerdos**.$q$, $q$ Las aclaraciones que solo explican cómo funciona algo que ya existe, como en qué cuentas y monedas pagamos, se muestran en la app y se aplican de inmediato, sin que tengas que volver a aceptar.$q$), updated_at = now() where agreement_id = c and locale = 'es';
  if not found then raise exception 'missing es Community Terms translation'; end if;
  update public.agreement_translations set body = pg_temp.patch(body, $q$- **7.7 Impuestos.** El Creador es un profesional independiente y es responsable de declarar y pagar todos los impuestos y cotizaciones sociales sobre lo que gana, en su propio país.$q$, E'\n' || $q$- **7.8 Cuentas, monedas y vales.** Tryp.com paga por transferencia bancaria a cuentas de la **zona SEPA** (en euros, o en la moneda local de un país SEPA, por ejemplo corona checa, corona noruega, corona sueca, corona danesa, esloti polaco o leu rumano) y a **cuentas bancarias del Reino Unido en libras esterlinas**. Tryp.com no puede pagar en cuentas fuera de la zona SEPA y del Reino Unido, ni en otras monedas (por ejemplo, una cuenta en pesos chilenos). El Creador que no pueda recibir una transferencia, o prefiera no hacerlo, siempre puede recibir el importe como un **vale de viaje de Tryp.com por el mismo valor** (en los términos de la cláusula 7.4), de modo que todos los Creadores pueden cobrar siempre.$q$), updated_at = now() where agreement_id = v and locale = 'es';
  if not found then raise exception 'missing es VIP translation'; end if;
  update public.agreement_translations set body = pg_temp.patch(pg_temp.patch(body, $q$- **Os prémios em dinheiro** são pagos por transferência bancária contra uma fatura que preparamos por ti com os dados de pagamento que guardares (autofaturação), normalmente nos 30 dias seguintes à publicação dos resultados. Tens de manter esses dados corretos; não conseguimos recuperar dinheiro enviado para uma conta que nos deste.$q$, E'\n' || $q$- **Onde e em que moeda pagamos.** Pagamos por transferência bancária para contas na **zona SEPA** (em euros, ou na moeda local de um país SEPA, por exemplo coroa checa, coroa norueguesa, coroa sueca, coroa dinamarquesa, zlóti polaco ou leu romeno) e para **contas bancárias do Reino Unido em libras esterlinas**. Não conseguimos pagar para contas fora da zona SEPA e do Reino Unido, nem noutras moedas (por exemplo, uma conta em pesos chilenos).$q$ || E'\n' || $q$- **Toda a gente pode sempre receber a sua recompensa.** Se não conseguires receber uma transferência numa conta que aceitamos, ou simplesmente preferires não o fazer, podes receber qualquer prémio em dinheiro como um **vale Tryp.com do mesmo valor**. Basta pedires à equipa (ethan@tryp.com ou uma mensagem na app) e nós emitimos.$q$), $q$continuam disponíveis em **Definições > Acordos**.$q$, $q$ Os esclarecimentos que apenas explicam como funciona algo que já existe, como as contas e moedas em que pagamos, aparecem na app e aplicam-se de imediato, sem teres de aceitar outra vez.$q$), updated_at = now() where agreement_id = c and locale = 'pt';
  if not found then raise exception 'missing pt Community Terms translation'; end if;
  update public.agreement_translations set body = pg_temp.patch(body, $q$- **7.7 Impostos.** O Criador é um prestador de serviços independente e é responsável por declarar e pagar todos os impostos e contribuições sociais sobre o que ganha, no seu próprio país.$q$, E'\n' || $q$- **7.8 Contas, moedas e vales.** A Tryp.com paga por transferência bancária para contas na **zona SEPA** (em euros, ou na moeda local de um país SEPA, por exemplo coroa checa, coroa norueguesa, coroa sueca, coroa dinamarquesa, zlóti polaco ou leu romeno) e para **contas bancárias do Reino Unido em libras esterlinas**. A Tryp.com não consegue pagar para contas fora da zona SEPA e do Reino Unido, nem noutras moedas (por exemplo, uma conta em pesos chilenos). O Criador que não possa ou prefira não receber uma transferência pode sempre receber o valor como um **vale de viagem Tryp.com do mesmo valor** (nos termos da cláusula 7.4), pelo que todos os Criadores podem sempre ser pagos.$q$), updated_at = now() where agreement_id = v and locale = 'pt';
  if not found then raise exception 'missing pt VIP translation'; end if;
  update public.agreement_translations set body = pg_temp.patch(pg_temp.patch(body, $q$- **Geldprämien** werden per Banküberweisung gegen eine Rechnung gezahlt, die wir für dich aus den von dir gespeicherten Zahlungsdaten erstellen (Gutschriftverfahren), in der Regel innerhalb von 30 Tagen nach Veröffentlichung der Ergebnisse. Du musst diese Daten korrekt halten; Geld, das auf ein von dir angegebenes Konto überwiesen wurde, können wir nicht zurückholen.$q$, E'\n' || $q$- **Wohin und in welcher Währung wir zahlen.** Wir zahlen per Banküberweisung auf Konten im **SEPA-Raum** (in Euro oder in der Landeswährung eines SEPA-Landes, zum Beispiel tschechische Krone, norwegische Krone, schwedische Krone, dänische Krone, polnischer Złoty oder rumänischer Leu) und auf **britische Bankkonten in Pfund Sterling**. Auf Konten außerhalb des SEPA-Raums und des Vereinigten Königreichs oder in anderen Währungen (zum Beispiel ein Konto in chilenischen Pesos) können wir nicht zahlen.$q$ || E'\n' || $q$- **Jeder kann immer belohnt werden.** Wenn du keine Überweisung auf ein von uns unterstütztes Konto erhalten kannst oder lieber nicht möchtest, kannst du jede Geldprämie stattdessen als **Tryp.com-Gutschein im gleichen Wert** erhalten. Frag einfach das Team (ethan@tryp.com oder per Nachricht in der App), dann stellen wir ihn aus.$q$), $q$bleibt unter **Einstellungen > Vereinbarungen** verfügbar.$q$, $q$ Klarstellungen, die nur erklären, wie etwas bereits funktioniert, etwa auf welche Konten und in welchen Währungen wir zahlen, werden in der App angezeigt und gelten sofort, ohne dass du erneut zustimmen musst.$q$), updated_at = now() where agreement_id = c and locale = 'de';
  if not found then raise exception 'missing de Community Terms translation'; end if;
  update public.agreement_translations set body = pg_temp.patch(body, $q$- **7.7 Steuern.** Der Creator ist selbständig tätig und ist dafür verantwortlich, alle Steuern und Sozialabgaben auf seine Einnahmen in seinem eigenen Land zu erklären und zu zahlen.$q$, E'\n' || $q$- **7.8 Konten, Währungen und Gutscheine.** Tryp.com zahlt per Banküberweisung auf Konten im **SEPA-Raum** (in Euro oder in der Landeswährung eines SEPA-Landes, zum Beispiel tschechische Krone, norwegische Krone, schwedische Krone, dänische Krone, polnischer Złoty oder rumänischer Leu) und auf **britische Bankkonten in Pfund Sterling**. Auf Konten außerhalb des SEPA-Raums und des Vereinigten Königreichs oder in anderen Währungen (zum Beispiel ein Konto in chilenischen Pesos) kann Tryp.com nicht zahlen. Ein Creator, der keine Überweisung erhalten kann oder lieber nicht möchte, kann den Betrag stattdessen immer als **Tryp.com-Reisegutschein im gleichen Wert** erhalten (nach Klausel 7.4), sodass jeder Creator immer bezahlt werden kann.$q$), updated_at = now() where agreement_id = v and locale = 'de';
  if not found then raise exception 'missing de VIP translation'; end if;
  update public.agreement_translations set body = pg_temp.patch(pg_temp.patch(body, $q$- **Premiile în bani** se plătesc prin transfer bancar pe baza unei facturi pe care o pregătim pentru tine din datele de plată pe care le salvezi (autofacturare), de regulă în 30 de zile de la publicarea rezultatelor. Trebuie să ții aceste date corecte; nu putem recupera banii trimiși într-un cont pe care ni l-ai dat.$q$, E'\n' || $q$- **Unde și în ce monedă plătim.** Plătim prin transfer bancar în conturi din **spațiul SEPA** (în euro sau în moneda locală a unei țări SEPA, de exemplu coroană cehă, coroană norvegiană, coroană suedeză, coroană daneză, zlot polonez sau leu românesc) și în **conturi bancare din Regatul Unit, în lire sterline**. Nu putem plăti în conturi din afara spațiului SEPA și a Regatului Unit și nici în alte monede (de exemplu un cont în pesos chilieni).$q$ || E'\n' || $q$- **Oricine poate primi mereu recompensa.** Dacă nu poți primi un transfer într-un cont pe care îl acceptăm sau pur și simplu preferi să nu, poți primi orice premiu în bani sub forma unui **voucher Tryp.com de aceeași valoare**. Cere-l echipei (ethan@tryp.com sau un mesaj în aplicație) și îl emitem.$q$), $q$rămâne disponibilă la **Setări > Acorduri**.$q$, $q$ Clarificările care doar explică cum funcționează ceva ce există deja, de exemplu în ce conturi și monede plătim, apar în aplicație și se aplică imediat, fără să trebuiască să accepți din nou.$q$), updated_at = now() where agreement_id = c and locale = 'ro';
  if not found then raise exception 'missing ro Community Terms translation'; end if;
  update public.agreement_translations set body = pg_temp.patch(body, $q$- **7.7 Taxe.** Creatorul este un colaborator independent și răspunde de declararea și plata tuturor impozitelor și contribuțiilor sociale aferente câștigurilor sale, în propria țară.$q$, E'\n' || $q$- **7.8 Conturi, monede și vouchere.** Tryp.com plătește prin transfer bancar în conturi din **spațiul SEPA** (în euro sau în moneda locală a unei țări SEPA, de exemplu coroană cehă, coroană norvegiană, coroană suedeză, coroană daneză, zlot polonez sau leu românesc) și în **conturi bancare din Regatul Unit, în lire sterline**. Tryp.com nu poate plăti în conturi din afara spațiului SEPA și a Regatului Unit și nici în alte monede (de exemplu un cont în pesos chilieni). Creatorul care nu poate sau preferă să nu primească un transfer poate primi oricând suma sub forma unui **voucher de călătorie Tryp.com de aceeași valoare** (în condițiile clauzei 7.4), astfel încât orice Creator poate fi plătit întotdeauna.$q$), updated_at = now() where agreement_id = v and locale = 'ro';
  if not found then raise exception 'missing ro VIP translation'; end if;
end $m$;

alter table public.agreement_translations enable trigger trg_agreement_translation_locked;
